UPDATE RESERVATION R
  JOIN `USER` U ON R.uidx = U.uidx
SET R.status = '수령완료',
    R.modify = NOW()
WHERE R.lbidx      = #{lbidx}
  AND U.userNumber = #{userNumber}
  AND R.pickupDate = #{pickupDate}
  AND R.status     = '예약중'
  AND R.delyn      = 'N'
